/// <summary>
/// The METDMFDownloadErrorLog class is responsible for logging staging errors by generating Excel files.
/// It provides methods to create mappings between staging table names and their corresponding record IDs and error messages,
/// and to generate Excel worksheets containing error logs for specific or all staging tables.
/// </summary>
class METDMFDownloadErrorLog
{
    DMFExecutionId  executionId;
    TableName       tableName;
    Map             stagingTableNameToRecIdMap  = new Map(Types::String,Types::Container);
    Map             stagingRecIdToErrorMap      = new Map(Types::Container,Types::Container);
    const str       excelName       = 'CrossPillarStagingDetails';
    const str       recId           = 'RecId';
    const str       error           = 'ErrorMessage';
    const str       fileExtension   = 'xlsx';
    const str       worksheet       = 'CrossPillarJournal';
}

Method.Source:
protected void new(DMFExecutionId _executionId, TableName _tableName = '')
{
    executionId = _executionId;
    tableName = _tableName;
}

public static METDMFDownloadErrorLog construct(DMFExecutionId _executionId, TableName _tableName = '')
{
    METDMFDownloadErrorLog  downloadErrorLog = new METDMFDownloadErrorLog(_executionId,_tableName);

    return downloadErrorLog;
}

/// <summary>
/// Logs staging errors by generating an Excel file with error logs for the given staging table.
/// Prompts the user to save the generated Excel file.
/// </summary>
public void logStagingError()
{
    var memoryStream = new System.IO.MemoryStream();

    using (var package = new OfficeOpenXml.ExcelPackage(memoryStream))
    {
        try
        {
            var worksheets = package.get_Workbook().get_Worksheets();

            // Error log for given staging table of given executionId
            if (tableName)
            {
                this.generateWorksheetForStaging(worksheets);
            }

            package.Save();
            DocuFileSaveResult saveResult = DocuFileSave::promptForSaveLocation(excelName,fileExtension);
            DocuFileSave::processSaveResult(memoryStream,saveResult);
        }
        catch(Exception::CLRError)
        {
            System.Exception ex = CLRInterop::getLastException();
            error(ex.Message);
        }
        catch
        {
            error("@SYS319214");
        }
    }
}

/// <summary>
/// Generates an Excel worksheet for a specific staging table containing error logs.
/// The worksheet includes headers and records with error messages for the given execution ID.
/// </summary>
/// <param name="_worksheets">The collection of Excel worksheets to add the new worksheet to.</param>
public void generateWorksheetForStaging(OfficeOpenXml.ExcelWorksheets _worksheets)
{
    TableId                         tableId = tableName2Id(tableName);
    FieldId                         execFieldId = fieldName2id(tableId, identifierStr(ExecutionId));
    Common                          commonStaging;
    var currentRow = 1;
    var ExcelWorksheet = _worksheets.Add(worksheet);
    var cells = ExcelWorksheet.get_Cells();

    SysDictTable dictTable = new SysDictTable(tableId);
    if (dictTable)
    {
        commonStaging = dictTable.makeRecord();
        Query q;
        QueryRun qr;
        QueryBuildDataSource qbd , qbds;
        q = new Query();
        qbd = q.addDataSource(tableNum(DMFStagingValidationLog));
        qbds = qbd.addDataSource(tableId);
        qbds.addLink(fieldNum(DMFStagingValidationLog,StagingRecId), fieldName2Id(tableId,recId));
        qbd.addRange(FieldNum(DMFStagingValidationLog,ErrorMessage)).value(sysquery::valueNotEmptyString());
        qbd.addRange(fieldNum(DMFStagingValidationLog,StagingTableName)).value(tableName);
        qbds.addRange(execFieldId).value(executionId);
        qr = new QueryRun(q);

        while (qr.next())
        {
            DMFStagingValidationLog validationLog = qr.get(tableNum(DMFStagingValidationLog));
            commonStaging = qr.get(tableId);

            if (currentRow == 1)
            {
                //Set Excel Headers in 1st row
                METDMFDownloadErrorLog::setExcelCellsHeaders(currentRow,cells,commonStaging);
            }
            currentRow ++;
            // Set Records in Excel worksheet
            METDMFDownloadErrorLog::setExcelCellsRecords(currentRow,cells,commonStaging,validationLog.ErrorMessage);

        }
    }
}

/// <summary>
///  Create worksheet header cells of table
/// </summary>
/// <param name = "_currentRow">currentRow</param>
/// <param name = "_cell">cell</param>
/// <param name = "_staging">staging</param>
/// <returns>cell_locale</returns>
private static OfficeOpenXml.ExcelRange setExcelCellsHeaders(int _currentRow, OfficeOpenXml.ExcelRange _cell, Common _staging)
{
    int                         currentColumn = 2;
    FieldId                     definitionGroup = fieldName2id(_staging.TableId, identifierStr(DefinitionGroup));
    DMFSourceXMLToEntityMap     sourceToEntityMap;
    DMFDefinitionGroupEntity    dmfdefinitionGroupEntity;
    DMFEntity                   dMFEntity;

    // First column set for error
    OfficeOpenXml.ExcelRange cell_locale = _cell.get_Item(_currentRow,1);
    cell_locale.set_Value(error);

    while select EntityField from sourceToEntityMap
        join DefinitionGroup from dmfdefinitionGroupEntity
            where sourceToEntityMap.DefinitionGroup == dmfdefinitionGroupEntity.DefinitionGroup
            && sourceToEntityMap.Entity == dmfdefinitionGroupEntity.Entity
        join EntityTable from dMFEntity
            where dmfdefinitionGroupEntity.Entity == dMFEntity.EntityName
            && dMFEntity.EntityTable == tableId2Name(_staging.TableId)
            && sourceToEntityMap.DefinitionGroup == _staging.(definitionGroup)
    {
        cell_locale = _cell.get_Item(_currentRow,currentColumn);
        cell_locale.set_Value(sourceToEntityMap.EntityField);
        cell_locale = null;
        currentColumn++;
    }

    return cell_locale;
}

/// <summary>
///  Create data for records of table
/// </summary>
/// <param name = "_currentRow">currentRow</param>
/// <param name = "_cell">cell</param>
/// <param name = "_staging">staging</param>
/// <param name = "_errorMessage">errorMessage</param>
/// <returns>cell_local</returns>
private static OfficeOpenXml.ExcelRange setExcelCellsRecords(int _currentRow, OfficeOpenXml.ExcelRange _cell, Common _staging, DMFErrorMessage _errorMessage)
{
    int                         currentColumn = 2;
    FieldId                     definitionGroup = fieldName2id(_staging.TableId, identifierStr(DefinitionGroup));
    DMFSourceXMLToEntityMap     sourceToEntityMap;
    DMFDefinitionGroupEntity    dmfdefinitionGroupEntity;
    DMFEntity                   dMFEntity;

    OfficeOpenXml.ExcelRange cell_locale = _cell.get_Item(_currentRow,1);
    cell_locale.set_Value(_errorMessage);

    while select EntityField from sourceToEntityMap
        join DefinitionGroup from dmfdefinitionGroupEntity
            where sourceToEntityMap.DefinitionGroup == dmfdefinitionGroupEntity.DefinitionGroup
            && sourceToEntityMap.Entity == dmfdefinitionGroupEntity.Entity
        join EntityTable from dMFEntity
            where dmfdefinitionGroupEntity.Entity == dMFEntity.EntityName
            && dMFEntity.EntityTable == tableId2Name(_staging.TableId)
            && sourceToEntityMap.DefinitionGroup == _staging.(definitionGroup)
    {
        cell_locale = _cell.get_Item(_currentRow,currentColumn);
        cell_locale.set_Value(any2Str(_staging.(fieldName2Id(_staging.TableId, sourceToEntityMap.EntityField))));
        cell_locale = null;
        currentColumn++;
    }

    return cell_locale;
}
